    leg_title: 'Informations légales',
    leg_subtitle: "Page de compatibilité qui centralise les informations légales utiles et renvoie vers les pages juridiques détaillées de Dok'péyi.",
    leg_compat_html: "<strong>Page legacy maintenue pour compatibilité.</strong> Les textes de référence détaillés sont désormais répartis sur les pages dédiées Mentions légales, CGV, Confidentialité et Cookies.",
    leg_toc_title: 'Sommaire',
