    leg_mentions_title: '1. Mentions légales',
    leg_mentions_intro: "Les informations d'éditeur, d'hébergement et de publication sont maintenues sur une page dédiée pour garantir leur mise à jour juridique sans duplication.",
    leg_open_notice: 'Ouvrir les mentions légales détaillées',
    leg_cgu_title: "2. Conditions Générales d'Utilisation",
    leg_cgu_intro: "L'utilisation du site Dok'péyi implique l'acceptation des présentes conditions générales d'utilisation. Elles encadrent l'accès au service et les responsabilités respectives de l'utilisateur et de Dok'péyi.",
    leg_cgu_warning_html: "<strong>Important :</strong> les documents générés par Dok'péyi constituent une aide à la rédaction. Ils doivent être relus et vérifiés avant tout usage officiel.",
    leg_cgu_li1: 'Le service est accessible 24h/24, 7j/7, sauf maintenance, incident technique ou cas de force majeure.',
    leg_cgu_li2: "L'utilisateur doit fournir des informations exactes et ne pas utiliser le service à des fins illicites, frauduleuses ou nuisibles.",
    leg_cgu_li3: 'Les contenus du site (logo, interface, textes, structure) sont protégés et ne peuvent être reproduits sans autorisation.',
    leg_cgu_li4: "Dok'péyi n'est pas un cabinet d'avocats ni une administration ; l'utilisateur reste responsable du dépôt et de l'usage final du document.",
    leg_cgv_title: '3. Conditions Générales de Vente',
    leg_cgv_intro: "Les tarifs, modalités de paiement, livraison, remboursement et avertissements liés à l'intelligence artificielle sont détaillés dans les CGV complètes.",
    leg_cgv_prices_intro: 'Rappel des tarifs publics actuellement affichés :',
    leg_cgv_payment: 'Le paiement est sécurisé. Les données bancaires sont traitées par les prestataires dédiés et ne transitent pas comme telles par Dok’péyi.',
    leg_cgv_delivery: 'Les services simples peuvent être livrés immédiatement ; les services soumis à relecture humaine sont finalisés sous 24 à 48 heures.',
    leg_cgv_refund: 'Les règles de remboursement, de rétractation et de médiation sont précisées dans la page CGV de référence.',
    leg_open_terms: 'Ouvrir les CGV détaillées',
    leg_conf_title: '4. Confidentialité & RGPD',
