    conf_title: 'Política de privacidade',
    conf_updated: 'Última atualização: abril de 2026 — Em conformidade com o Regulamento (UE) 2016/679 (RGPD) e a Lei Informatique et Libertés francesa',
    conf_controller_title: '1. Responsável pelo tratamento',
    conf_controller_service: "<strong>Dok'péyi</strong> — serviço online de apoio administrativo para a Guiana Francesa.",
    conf_controller_desc: "Dok'péyi determina as finalidades e os meios de tratamento dos dados pessoais recolhidos no site.",
    conf_data_categories_title: '2. Dados recolhidos',
    conf_data_categories_intro: "No âmbito da prestação do serviço, Dok'péyi recolhe as seguintes categorias de dados:",
    conf_identity_title: 'Dados de identificação e contacto',
    conf_identity_li1: 'Nome e apelido',
    conf_identity_li2: 'Endereço de email',
    conf_identity_li3: 'Número de telefone (WhatsApp)',
    conf_request_title: 'Dados relacionados com o pedido',
    conf_request_li1: 'Situação administrativa (tempo de residência, nacionalidade, visto, situação familiar, situação profissional, rendimentos...)',
    conf_request_li2: 'Informações profissionais (cargo, experiências, formações, competências) para CV e cartas',
    conf_request_li3_html: 'Documentos enviados pelo utilizador para pré-preenchimento (PDF ou imagem analisados por <code>/api/extract-doc</code>)',
    conf_request_li4: 'Documentos gerados (CV, cartas, ofícios, dossiês, guias)',
    conf_payment_title: 'Dados de pagamento',
    conf_payment_p1_html: "Os dados bancários (número do cartão, criptograma...) <strong>nunca passam pelos servidores da Dok'péyi</strong>. São tratados diretamente pelo nosso prestador de pagamento (Stripe). A Dok'péyi conserva apenas o identificador da transação e o montante pago para fins contabilísticos e de acompanhamento.",
    conf_technical_title: 'Dados técnicos',
    conf_technical_li1: 'Endereço IP (utilizado para rate-limiting, não armazenado de forma duradoura)',
    conf_technical_li2: 'Tipo de navegador e dispositivo',
    conf_technical_li3: 'Data e hora das ações no site',
    conf_purposes_title: '3. Finalidades e bases legais',
    conf_table_purpose: 'Finalidade',
    conf_table_basis: 'Base legal',
    conf_purpose_1: 'Geração do documento encomendado (CV, carta, dossiê...)',
    conf_basis_1: 'Execução do contrato (art. 6.1.b RGPD)',
    conf_purpose_2: 'Faturação e acompanhamento das encomendas',
    conf_basis_2: 'Execução do contrato + obrigação legal',
    conf_purpose_3: 'Relação com o cliente e suporte',
    conf_basis_3: 'Execução do contrato',
    conf_purpose_4: 'Segurança do serviço (rate-limiting, luta antifraude)',
    conf_basis_4: 'Interesse legítimo (art. 6.1.f RGPD)',
    conf_purpose_5: 'Obrigações contabilísticas e fiscais',
    conf_basis_5: 'Obrigação legal (art. 6.1.c RGPD)',
    conf_retention_title: '4. Prazo de conservação',
    conf_retention_li1_html: '<strong>Dados da encomenda e documentos gerados:</strong> 12 meses após a última encomenda, depois eliminação ou arquivo anonimizado.',
    conf_retention_li2_html: '<strong>Dados de faturação:</strong> 10 anos (obrigação contabilística francesa).',
    conf_retention_li3_html: '<strong>Dados técnicos (rate-limit, logs):</strong> máximo de 12 meses corridos.',
    conf_retention_li4_html: '<strong>Preferências de cookies:</strong> 30 dias (armazenamento local no navegador).',
    conf_processors_title: '5. Destinatários e subcontratantes',
    conf_processors_intro: "Dok'péyi recorre aos seguintes subcontratantes para prestar o serviço. Cada um está vinculado por um acordo de tratamento de dados (DPA) conforme o artigo 28 do RGPD quando aplicável:",
    conf_table_processor: 'Subcontratante',
    conf_table_role: 'Função',
    conf_table_location: 'Localização',
    conf_proc_1_role: 'Geração de texto por IA',
    conf_proc_1_location: 'Estados Unidos (cláusulas contratuais-tipo)',
    conf_proc_2_role: 'Chat interno com IA (fallback)',
    conf_proc_2_location: 'Estados Unidos (cláusulas contratuais-tipo)',
    conf_proc_3_role: 'Alojamento do site e das Edge Functions',
    conf_proc_3_location: 'Estados Unidos (cláusulas contratuais-tipo)',
    conf_proc_4_role: 'Tratamento de pagamentos com cartão',
    conf_proc_4_location: 'Irlanda / Estados Unidos',
    conf_proc_5_role: 'Base de dados Realtime (encomendas)',
    conf_proc_5_location: 'UE — europe-west1',
    conf_proc_6_role: 'Envio de emails transacionais',
    conf_proc_6_location: 'Estados Unidos (cláusulas contratuais-tipo)',
    conf_processors_p1_html: 'As transferências de dados para fora da UE, nomeadamente para os Estados Unidos, são enquadradas pelas <strong>Cláusulas Contratuais-Tipo</strong> da Comissão Europeia e, quando aplicável, pelo <strong>Data Privacy Framework</strong>.',
    conf_processors_p2: 'Nenhum dado pessoal é vendido, alugado ou cedido a terceiros para fins comerciais.',
    conf_rights_title: '6. Os seus direitos',
    conf_rights_intro_html: 'Enquanto titular dos dados, dispõe dos seguintes direitos:',
    conf_rights_li1_html: '<strong>Direito de acesso</strong> — obter a confirmação de que os seus dados são tratados e uma cópia dos mesmos.',
    conf_rights_li2_html: '<strong>Direito de retificação</strong> — corrigir dados inexatos ou incompletos.',
    conf_rights_li3_html: '<strong>Direito ao apagamento</strong> — solicitar a eliminação dos seus dados (“direito a ser esquecido”) sob determinadas condições.',
    conf_rights_li4_html: '<strong>Direito à limitação</strong> — solicitar a suspensão do tratamento em certos casos.',
    conf_rights_li5_html: '<strong>Direito de oposição</strong> — opor-se a um tratamento baseado em interesse legítimo.',
    conf_rights_li6_html: '<strong>Direito à portabilidade</strong> — receber os seus dados num formato estruturado e legível.',
    conf_rights_li7_html: '<strong>Direito de retirar o consentimento</strong> a qualquer momento (para os tratamentos baseados no consentimento).',
    conf_rights_li8_html: '<strong>Direito de definir diretivas pós-morte</strong> relativas aos seus dados.',
    conf_rights_request_html: 'Para exercer estes direitos, envie o seu pedido para <a href="mailto:contact@dok-peyi.fr">contact@dok-peyi.fr</a> indicando a sua identidade. Receberá resposta no prazo máximo de <strong>um mês</strong>.',
    conf_dpo_title: '7. Encarregado da proteção de dados (DPO)',
    conf_dpo_p1: "A Dok'péyi não é legalmente obrigada a designar um DPO, mas nomeou um ponto de contacto dedicado para todas as questões relativas à proteção de dados:",
    conf_security_title: '8. Segurança dos dados',
    conf_security_intro: "A Dok'péyi implementa medidas técnicas e organizativas adequadas para proteger os seus dados contra destruição, perda, alteração ou divulgação não autorizada:",
    conf_security_li1: 'Encriptação dos dados em trânsito (HTTPS / TLS)',
    conf_security_li2: 'Regras de segurança Firebase (controlo de acesso por função)',
    conf_security_li3: 'Cabeçalhos HTTP de segurança (CSP, HSTS, X-Frame-Options...)',
    conf_security_li4: 'Autenticação das contas administrativas com proteção contra força bruta',
    conf_security_li5: 'Rate-limiting nas APIs sensíveis',
    conf_security_li6: 'Verificação de assinatura (HMAC-SHA256) nos webhooks de pagamento',
    conf_authority_title: '9. Autoridade de controlo',
    conf_authority_p1: 'Nos termos do artigo 77 do RGPD, tem o direito de apresentar reclamação junto da autoridade de controlo francesa:',
    conf_authority_phone: 'Telefone: 01 53 73 22 22',
    conf_authority_site: 'Site:',
    conf_changes_title: '10. Alterações à política',
    conf_changes_p1: "A Dok'péyi pode alterar a presente política de privacidade. Qualquer alteração substancial será comunicada no site ou por email. A versão aplicável é a que estiver em vigor na data da sua última encomenda.",
    conf_contact_title: '11. Contacto',
    conf_contact_intro: 'Para qualquer questão relativa a esta política ou ao tratamento dos seus dados pessoais:',
