    cookies_nav_home: 'Voltar ao início',
    cookies_title: 'Política de cookies',
    cookies_updated: 'Última atualização: abril de 2026',
    cookies_summary_html: '<strong>🍪 Em resumo — Dok\'péyi usa cookies com sobriedade:</strong><br>São utilizados apenas cookies <strong>estritamente necessários</strong> ao funcionamento do serviço. Nenhum cookie publicitário, nenhum rastreador de terceiros, nenhuma partilha com redes publicitárias.',
    cookies_definition_title: '1. O que é um cookie?',
    cookies_definition_p1: 'Um cookie é um pequeno ficheiro de texto colocado no seu dispositivo (computador, smartphone, tablet) pelo navegador quando visita um site. Permite ao site memorizar informações sobre a sua visita (idioma, sessão, preferências).',
    cookies_definition_p2_html: 'A Dok\'péyi também utiliza outras tecnologias semelhantes: <code>localStorage</code> (armazenamento local do navegador) e <code>sessionStorage</code> (armazenamento de sessão, apagado ao fechar o separador).',
    cookies_used_title: '2. Cookies utilizados na Dok\'péyi',
    cookies_used_intro: 'Apenas os cookies seguintes, todos estritamente necessários ao funcionamento do serviço, são utilizados:',
    cookies_table_name: 'Nome',
    cookies_table_purpose: 'Finalidade',
    cookies_table_duration: 'Duração',
    cookies_table_type: 'Tipo',
    cookies_cookie_ok_purpose: 'Memorizar a sua aceitação do banner de cookies',
    cookies_cookie_ok_duration: '30 dias',
    cookies_cookie_draft_purpose: 'Cópia temporária do formulário de pedido (wizard)',
    cookies_cookie_draft_duration: 'Sessão (fecho do separador)',
    cookies_cookie_lang_purpose: 'Memorizar o idioma escolhido para a interface',
    cookies_cookie_lang_duration: '1 ano',
    cookies_cookie_stripe_name: 'Cookies Stripe',
    cookies_cookie_stripe_purpose: 'Segurança da sessão de pagamento (colocados apenas durante o pagamento via Stripe)',
    cookies_cookie_stripe_duration: 'Sessão',
    cookies_cookie_stripe_type: 'Terceiro estritamente necessário',
    cookies_we_do_not_title: '3. O que não fazemos',
    cookies_we_do_not_li1: '❌ Nenhum cookie publicitário, nenhum direcionamento comportamental',
    cookies_we_do_not_li2: '❌ Nenhum cookie de terceiros para tracking (Google Analytics, Facebook Pixel, etc.)',
    cookies_we_do_not_li3: '❌ Nenhuma revenda ou partilha de dados com redes publicitárias',
    cookies_we_do_not_li4: '❌ Nenhum perfilamento para fins comerciais',
    cookies_consent_title: '4. Consentimento',
    cookies_consent_p1: 'Em conformidade com a regulamentação (RGPD, diretiva ePrivacy, recomendações da CNIL), os cookies estritamente necessários ao funcionamento de um serviço solicitado pelo utilizador não exigem consentimento prévio.',
    cookies_consent_p2_html: 'Ainda assim, a Dok\'péyi apresenta um banner informativo na sua primeira visita para o informar sobre a utilização destes cookies. Ao clicar em « Aceito », confirma que tomou conhecimento. O banner deixará de aparecer nas suas visitas seguintes.',
    cookies_manage_title: '5. Como gerir os cookies?',
    cookies_manage_intro: 'Pode, a qualquer momento, apagar os cookies já colocados ou impedir a sua colocação através das definições do seu navegador:',
    cookies_manage_chrome: '<strong>Chrome :</strong> Definições → Privacidade e segurança → Cookies e outros dados dos sites',
    cookies_manage_firefox: '<strong>Firefox :</strong> Definições → Privacidade e segurança → Cookies e dados dos sites',
    cookies_manage_safari: '<strong>Safari :</strong> Preferências → Privacidade → Gerir os dados dos sites',
    cookies_manage_edge: '<strong>Edge :</strong> Definições → Cookies e permissões do site',
    cookies_manage_p2_html: 'Também pode limpar o armazenamento local (<code>localStorage</code> / <code>sessionStorage</code>) através das ferramentas de desenvolvimento do seu navegador.',
    cookies_manage_warning_html: '<strong>Atenção:</strong> bloquear os cookies estritamente necessários pode impedir o bom funcionamento do site (perda do carrinho, desconexão…).',
    cookies_changes_title: '6. Alterações',
    cookies_changes_p1: 'A presente política de cookies pode ser atualizada para refletir evoluções técnicas ou regulamentares. Qualquer alteração substancial será indicada nesta página e, se necessário, através de um novo banner de consentimento.',
    cookies_contact_title: '7. Contacto',
    cookies_contact_intro: 'Para qualquer questão relativa aos cookies:',
    cookies_footer_home: 'Início',
    leg_nav_home: 'Voltar à página inicial',
    leg_title: 'Informações legais',
    leg_subtitle: 'Página de compatibilidade que centraliza as informações legais úteis e encaminha para as páginas jurídicas detalhadas da Dok\'péyi.',
    leg_compat_html: '<strong>Página legacy mantida por compatibilidade.</strong> Os textos jurídicos de referência estão agora distribuídos pelas páginas dedicadas de Aviso legal, Condições de venda, Privacidade e Cookies.',
    leg_toc_title: 'Sumário',
    leg_toc_mentions: '1. Aviso legal',
    leg_toc_cgu: '2. Condições Gerais de Utilização',
    leg_toc_cgv: '3. Condições Gerais de Venda',
    leg_toc_conf: '4. Privacidade e RGPD',
    leg_toc_cookies: '5. Política de cookies',
    leg_mentions_title: '1. Aviso legal',
    leg_mentions_intro: 'As informações do editor, alojamento e publicação são mantidas numa página dedicada para garantir atualização jurídica sem duplicação.',
    leg_open_notice: 'Abrir o aviso legal detalhado',
    leg_cgu_title: '2. Condições Gerais de Utilização',
    leg_cgu_intro: 'A utilização do site Dok\'péyi implica a aceitação das presentes condições gerais de utilização. Elas enquadram o acesso ao serviço e as responsabilidades respetivas do utilizador e da Dok\'péyi.',
    leg_cgu_warning_html: '<strong>Importante:</strong> os documentos gerados pela Dok\'péyi constituem uma ajuda à redação. Devem ser revistos e verificados antes de qualquer utilização oficial.',
    leg_cgu_li1: 'O serviço está acessível 24 horas por dia, 7 dias por semana, salvo manutenção, incidente técnico ou força maior.',
    leg_cgu_li2: 'O utilizador deve fornecer informações exatas e não utilizar o serviço para fins ilícitos, fraudulentos ou prejudiciais.',
    leg_cgu_li3: 'Os conteúdos do site (logótipo, interface, textos, estrutura) estão protegidos e não podem ser reproduzidos sem autorização.',
    leg_cgu_li4: 'A Dok\'péyi não é um escritório de advogados nem uma administração; o utilizador continua responsável pelo depósito e uso final do documento.',
    leg_cgv_title: '3. Condições Gerais de Venda',
    leg_cgv_intro: 'Tarifas, pagamento, entrega, reembolso e avisos ligados à inteligência artificial estão detalhados nas CGV completas.',
    leg_cgv_prices_intro: 'Resumo das tarifas públicas atualmente apresentadas:',
    leg_cgv_payment: 'O pagamento é seguro. Os dados bancários são tratados pelos prestadores dedicados e não transitam como tais pela Dok\'péyi.',
    leg_cgv_delivery: 'Os serviços simples podem ser entregues imediatamente; os serviços sujeitos a revisão humana são finalizados em 24 a 48 horas.',
    leg_cgv_refund: 'As regras de reembolso, retratação e mediação estão detalhadas na página CGV de referência.',
    leg_open_terms: 'Abrir as CGV detalhadas',
    leg_conf_title: '4. Privacidade e RGPD',
    leg_conf_intro: 'A Dok\'péyi trata os dados pessoais necessários para a geração, pagamento e entrega dos documentos, em conformidade com o RGPD e a legislação francesa.',
    leg_conf_li1: 'Dados de identificação e contacto',
    leg_conf_li2: 'Dados ligados ao pedido administrativo ou profissional',
    leg_conf_li3: 'Dados técnicos e de pagamento estritamente necessários',
    leg_open_privacy: 'Abrir a política de privacidade detalhada',
    leg_cookies_title: '5. Política de cookies',
    leg_cookies_intro: 'A Dok\'péyi adota uma política sóbria: apenas cookies e armazenamentos estritamente necessários ao funcionamento do serviço e do pagamento.',
    leg_cookies_li1: 'Memorização do banner de cookies e da língua escolhida',
