    ml_law_title: 'Lwa aplikab',
    ml_law_p1_html: 'Mansyon sa yo soumèt a dwa fransè. Nenpòt litij depann sèlman de jiridiksyon tribinal fransè yo; tribinal konpetan an se sa ki nan <strong>Cayenne (Giyàn fransè)</strong>.',
    ml_contact_title: 'Kontak',
    ml_contact_intro: 'Pou nenpòt kestyon sou sit la oswa sou kontni li:',
    ml_footer_home: 'Akèy',
    cgv_nav_home: 'Retounen sou akèy la',
    cgv_title: 'Kondisyon Jeneral Vant',
    cgv_updated: 'Dènye mizajou: avril 2026',
    cgv_section_1_title: '1. Prezantasyon sèvis la',
    cgv_section_1_p1: 'Dok\'péyi se yon sèvis anliy ki ede nan redaksyon ak preparasyon dokiman administratif pou rezidan Giyàn fransè, epi pi lajman pou tout piblik frankofòn ki ap fè demach administratif fransè.',
    cgv_section_1_p2: 'Sèvis la pèmèt jenerasyon dokiman sa yo ak entèlijans atifisyèl: CV, lèt motivasyon, kourye ofisyèl, dosye administratif, gid pou tit de séjour, dokiman fiskal ak dosye natiralizasyon.',
    cgv_section_1_p3: 'Kondisyon Jeneral Vant sa yo (ki rele “CGV”) gouvène tout relasyon ant Dok\'péyi ak kliyan li yo.',
    cgv_section_2_title: '2. Pri',
    cgv_section_2_intro: 'Pri sa yo se tout taks ladan, an ero, pou chak dokiman ki jenere:',
    cgv_table_service: 'Sèvis',
    cgv_table_price: 'Pri',
    cgv_rate_cv: 'CV pwofesyonèl',
    cgv_rate_lettre: 'Lèt motivasyon',
    cgv_rate_courrier: 'Kourye ofisyèl',
    cgv_rate_dossier: 'Dosye administratif (CAF, lojman, èd sosyal…)',
    cgv_rate_sejour: 'Tit de séjour (gid pèsonalize)',
    cgv_rate_impot: 'Avi taks (konpreyansyon, èd, lèt)',
    cgv_rate_naturalisation: 'Natiralizasyon (elijiblite, dosye, lèt)',
    cgv_cv_options_title: 'Opsyon ak sipleman CV',
    cgv_cv_options_intro: 'Modèl CV premium yo pwopoze kòm sipleman sou pri debaz CV a:',
    cgv_table_template: 'Modèl CV',
    cgv_table_supplement: 'Sipleman',
    cgv_cv_option_classic: 'Klasik (enkli pa default)',
    cgv_cv_option_corporate: 'Corporate',
    cgv_cv_option_impact: 'Impact',
    cgv_cv_option_elite: 'Elite',
    cgv_cv_option_prestige: 'Prestige',
    cgv_cv_option_executive: 'Executive',
    cgv_other_options_title: 'Lòt opsyon',
    cgv_other_option_translation_html: '<strong>Tradiksyon dokiman an</strong> (angle, kreyòl, pòtigè): <span class="price">+3 €</span>',
    cgv_other_option_mods_html: '<strong>Modifikasyon siplemantè</strong> — <strong>2 modifikasyon gratis</strong> sou chak dokiman apre previsualizasyon. Apre sa, pri ki aplikab la ap kominike anvan tout fakti epi li pral mande akò klè kliyan an.',
    cgv_section_3_title: '3. Kòmand ak peman',
    cgv_section_3_p1: 'Kòmand lan fèt atravè entèfas sit la (service.html) an twa etap: chwazi sèvis la, ranpli enfòmasyon yo, fè peman an.',
    cgv_section_3_p2_html: 'Peman an fèt anliy, an sekirite, atravè <strong>Stripe</strong>. Peman manyèl pa <strong>PayPal</strong> ak <strong>Mobile Money (Momo)</strong> disponib tou sou demann.',
    cgv_section_3_p3: 'Done bankè yo pa janm pase sou serve Dok\'péyi yo: se dirèkteman founisè peman an ki trete yo.',
    cgv_section_4_title: '4. Delè livrezon',
    cgv_section_4_p1_html: 'Jenerasyon dokiman an pa entèlijans atifisyèl se <strong>prèske imedya</strong> (kèk segonn). Dokiman an disponib an previsualizasyon dèske jenerasyon an fini.',
    cgv_section_4_p2_html: 'Pou sèvis ki mande verifikasyon manyèl pa yon manm ekip la (<strong>Tit de séjour</strong>, <strong>Natiralizasyon</strong>), livrezon final la fèt nan yon delè <strong>24 a 48 èdtan</strong> apre validasyon administratif la, pa imèl.',
    cgv_section_4_p3_html: 'Pou lòt sèvis yo, livrezon an fèt <strong>imedyatman</strong> apre konfimasyon peman an, pa imèl oswa telechajman dirèk.',
    cgv_section_5_title: '5. Politik ranbousman',
    cgv_refund_intro: 'Dapre atik L.221-28 Kòd Konsomasyon an, kliyan an benefisye garanti sa yo:',
    cgv_refund_delay_html: '<strong>Dokiman ki pa delivre nan 72h</strong> apre peman (sof si kliyan an te mande yon reta oswa li pa reponn ekip la): ranbousman total sou demann.',
    cgv_refund_error_html: '<strong>Dokiman ki klèman erone oswa ki pa ka sèvi</strong>: koreksyon priyoritè gratis oswa, si sa enposib, ranbousman pasyèl oswa total selon ka a.',
    cgv_refund_tech_html: '<strong>Erè teknik oswa fakti an doub</strong>: ranbousman total nan 14 jou.',
    cgv_refund_request_html: 'Tout demann ranbousman dwe voye nan <a href="mailto:contact@dok-peyi.fr">contact@dok-peyi.fr</a> ak nimewo kòmand lan ak rezon an.',
    cgv_retract_title: '6. Dwa retrè',
    cgv_retract_p1_html: 'An aplikasyon atik L.221-18 Kòd Konsomasyon an, kliyan an gen yon delè <strong>14 jou kalandriye</strong> apati konfimasyon kòmand li pou egzèse dwa retrè li, san li pa bezwen bay rezon.',
    cgv_retract_p2_html: '<strong>Eksepsyon — atik L.221-28 13° Kòd Konsomasyon an:</strong> dwa retrè a pa ka egzèse pou kontra ki bay <strong>kontni dijital ki pa sou yon sipò materyèl</strong> lè ekzekisyon an te kòmanse apre akò klè kliyan an ak renonsyasyon klè li sou dwa retrè a. Lè kliyan an valide kòmand li, li rekonèt dokiman an ap delivre imedyatman epi li renonse ak dwa retrè li pou kontni sa a.',
    cgv_retract_p3: 'Dwa retrè a rete aplikab si dokiman an pa t delivre nan delè ki prevwa yo (atik 4).',
    cgv_ai_title: '7. Avètisman sou entèlijans atifisyèl',
    cgv_disclaimer_html: '<strong>⚠️ Avètisman IA — li sa ak anpil atansyon</strong><br><br>Dokiman ki jenere pa entèlijans atifisyèl yo bay kòm èd pou redaksyon. Yo pa konstitiye konsèy legal pwofesyonèl.<br><br>Pou demach konplèks (<strong>tit de séjour, natiralizasyon, litij fiskal, rekou administratif</strong>), nou rekòmande anpil pou konsilte yon pwofesyonèl lalwa (avoka) oswa yon asosyasyon espesyalize — espesyalman <strong>CIMADE Guyane</strong> (èd gratis pou etranje) oswa yon pwen aksè ak dwa.<br><br>Dok\'péyi pa pran responsablite si yon dokiman ki jenere itilize san verifikasyon nan yon demach ofisyèl.',
    cgv_liability_title: '8. Responsablite',
    cgv_liability_p1: 'Dok\'péyi fè tout sa li kapab pou asire kalite dokiman yo. Men kliyan an rete responsab pou verifye epi sèvi ak dokiman yo bay li yo.',
    cgv_liability_p2: 'Dok\'péyi pa ka responsab pou:',
    cgv_liability_li1: 'konsekans enfòmasyon ki pa egzak kliyan an bay;',
    cgv_liability_li2: 'refi yon demach administratif pa administrasyon konpetan an;',
    cgv_liability_li3: 'yon entèripsyon tanporè sèvis la ki lye ak eberjè a oswa sèvis twazyèm pati;',
    cgv_liability_li4: 'move itilizasyon dokiman an pa kliyan an oswa pa yon lòt moun.',
    cgv_data_title: '9. Pwoteksyon done pèsonèl',
    cgv_data_p1_html: 'Dok\'péyi kolekte epi trete done pèsonèl kliyan yo selon RGPD la. Pou detay sou tretman yo, objektif yo, dire konsèvasyon an ak dwa kliyan an, gade <a href="/confidentialite">Politik konfidansyalite</a> a.',
    cgv_changes_title: '10. Chanjman CGV yo',
    cgv_changes_p1: 'Dok\'péyi rezève dwa pou modifye CGV sa yo nenpòt lè. CGV ki aplikab yo se sa ki an vigè nan dat kliyan an pase kòmand lan. Tout chanjman sibstansyèl ap notifye pa imèl bay kliyan ki konsène yo.',
    cgv_jurisdiction_title: '11. Lwa aplikab ak jiridiksyon konpetan',
    cgv_jurisdiction_p1_html: 'CGV sa yo soumèt anba <strong>dwa fransè</strong>.',
    cgv_jurisdiction_p2_html: 'Si pa gen rezolisyon amikal, tout litij sou entèpretasyon oswa egzekisyon yo tonbe anba konpetans eksklizif <strong>Tribinal Jidisyè Cayenne</strong>.',
    cgv_jurisdiction_p3: 'Dapre atik L.612-1 Kòd Konsomasyon an, kliyan konsomatè a kapab itilize gratis yon medyatè konsomasyon pou rezoud yon litij amikalman. Kowòdone medyatè a ap kominike sou demann.',
    cgv_contact_title: '12. Kontak',
    cgv_contact_intro: 'Pou tout kestyon sou CGV sa yo oswa sou yon kòmand:',
    cgv_footer_home: 'Akèy',
