    conf_processors_intro: "Dok'péyi itilize soutretan sa yo pou bay sèvis la. Chak ladan yo angaje ak yon akò tretman done (DPA) ki konfòm ak atik 28 RGPD la lè sa aplikab:",
    conf_table_processor: 'Soutretan',
