    conf_proc_6_location: 'Etazini (kloz kontra estanda)',
    conf_processors_p1_html: 'Transfè done andeyò Inyon Ewopeyen an, sitou nan Etazini, kouvri pa <strong>Kloz Kontra Estanda</strong> Komisyon Ewopeyen an epi, si sa aplikab, pa <strong>Data Privacy Framework</strong> la.',
    conf_processors_p2: 'Pa gen okenn done pèsonèl yo vann, lwe oswa bay twazyèm pati pou rezon komèsyal.',
    conf_rights_title: '6. Dwa ou',
    conf_rights_intro_html: 'Kòm moun done yo konsène a, ou gen dwa sa yo:',
    conf_rights_li1_html: '<strong>Dwa aksè</strong> — jwenn konfimasyon ke done ou yo ap trete ak yon kopi yo.',
    conf_rights_li2_html: '<strong>Dwa koreksyon</strong> — fè korije done ki pa egzak oswa ki pa konplè.',
    conf_rights_li3_html: '<strong>Dwa efasman</strong> — mande sipresyon done ou yo (“dwa pou bliye”) anba sèten kondisyon.',
    conf_rights_li4_html: '<strong>Dwa limitasyon</strong> — mande sispansyon tretman an nan kèk ka.',
    conf_rights_li5_html: '<strong>Dwa opozisyon</strong> — opoze ak yon tretman ki baze sou enterè lejitim.',
    conf_rights_li6_html: '<strong>Dwa pòtablite</strong> — resevwa done ou yo nan yon fòma estriktire ak lizib.',
    conf_rights_li7_html: '<strong>Dwa pou retire konsantman ou</strong> nenpòt kilè (pou tretman ki baze sou konsantman).',
    conf_rights_li8_html: '<strong>Dwa pou bay direktiv apre lanmò</strong> sou done ou yo.',
    conf_rights_request_html: 'Pou egzèse dwa sa yo, voye demann ou pa imel nan <a href="mailto:contact@dok-peyi.fr">contact@dok-peyi.fr</a> epi presize idantite ou. Yo va reponn ou nan yon delè maksimòm <strong>yon mwa</strong>.',
    conf_dpo_title: '7. Delege pwoteksyon done (DPO)',
    conf_dpo_p1: "Dok'péyi pa legalman oblije nonmen yon DPO, men li fikse yon pwen kontak espesyal pou tout kestyon ki gen rapò ak pwoteksyon done:",
    conf_security_title: '8. Sekirite done yo',
    conf_security_intro: "Dok'péyi mete ann aplikasyon mezi teknik ak òganizasyonèl ki adapte pou pwoteje done ou yo kont destriksyon, pèt, chanjman oswa divilgasyon san otorizasyon:",
    conf_security_li1: 'Chifreman done pandan transmisyon (HTTPS / TLS)',
    conf_security_li2: 'Règ sekirite Firebase (kontwòl aksè pa wòl)',
    conf_security_li3: 'Headers HTTP sekirite (CSP, HSTS, X-Frame-Options...)',
    conf_security_li4: 'Otantifikasyon kont administratè yo ak pwoteksyon kont atak fòs brit',
    conf_security_li5: 'Rate-limiting sou API sansib yo',
    conf_security_li6: 'Verifikasyon siyati (HMAC-SHA256) sou webhooks peman yo',
    conf_authority_title: '9. Otorite kontwòl',
    conf_authority_p1: 'Dapre atik 77 RGPD la, ou gen dwa depoze yon plent bò kote otorite kontwòl franse a:',
    conf_authority_phone: 'Telefòn : 01 53 73 22 22',
    conf_authority_site: 'Sit :',
    conf_changes_title: '10. Chanjman nan politik la',
    conf_changes_p1: "Dok'péyi ka modifye politik konfidansyalite sa a. Nenpòt chanjman enpòtan ap anonse sou sit la oswa pa imel. Vèsyon ki aplikab la se sila ki an vigè nan dat dènye kòmand ou a.",
    conf_contact_title: '11. Kontak',
    conf_contact_intro: 'Pou nenpòt kestyon sou politik sa a oswa sou tretman done pèsonèl ou yo:',
    conf_footer_home: 'Akèy',
    cookies_nav_home: 'Retounen sou akèy la',
    cookies_title: 'Politik cookies',
    cookies_updated: 'Dènye mizajou: avril 2026',
    cookies_summary_html: '<strong>🍪 An rezime — Dok\'péyi rete senp ak cookies:</strong><br>Se sèlman cookies <strong>estrikteman nesesè</strong> pou sèvis la mache yo itilize. Pa gen cookie piblisite, pa gen tracker twazyèm pati, pa gen pataj ak rezo piblisite.',
    cookies_definition_title: '1. Kisa yon cookie ye?',
    cookies_definition_p1: 'Yon cookie se yon ti fichye tèks navigatè a depoze sou aparèy ou (òdinatè, telefòn, tablèt) lè ou vizite yon sit. Li pèmèt sit la sonje kèk enfòmasyon sou vizit ou (lang, sesyon, preferans).',
    cookies_definition_p2_html: 'Dok\'péyi sèvi tou ak lòt teknoloji ki sanble : <code>localStorage</code> (depo lokal navigatè a) ak <code>sessionStorage</code> (depo sesyon an, ki efase lè onglet la fèmen).',
    cookies_used_title: '2. Cookies Dok\'péyi itilize',
    cookies_used_intro: 'Se sèlman cookies sa yo, tout estrikteman nesesè pou sèvis la mache, yo itilize :',
    cookies_table_name: 'Non',
    cookies_table_purpose: 'Finalite',
    cookies_table_duration: 'Dire',
    cookies_table_type: 'Tip',
    cookies_cookie_ok_purpose: 'Sonje ou te aksepte banyè cookies la',
    cookies_cookie_ok_duration: '30 jou',
    cookies_cookie_draft_purpose: 'Sovgad tanporè fòmilè kòmand la (wizard)',
    cookies_cookie_draft_duration: 'Sesyon (lè onglet la fèmen)',
    cookies_cookie_lang_purpose: 'Sonje lang ou chwazi pou koòdone a',
    cookies_cookie_lang_duration: '1 an',
    cookies_cookie_stripe_name: 'Cookies Stripe',
    cookies_cookie_stripe_purpose: 'Sekirize sesyon peman an (yo depoze sèlman pandan peman Stripe la)',
    cookies_cookie_stripe_duration: 'Sesyon',
    cookies_cookie_stripe_type: 'Twazyèm pati estrikteman nesesè',
    cookies_we_do_not_title: '3. Sa nou pa fè',
    cookies_we_do_not_li1: '❌ Pa gen cookie piblisite, pa gen vize konpòtman',
    cookies_we_do_not_li2: '❌ Pa gen cookie twazyèm pati pou tracking (Google Analytics, Facebook Pixel, elatriye)',
    cookies_we_do_not_li3: '❌ Pa gen revant ni pataj done ak rezo piblisite',
    cookies_we_do_not_li4: '❌ Pa gen pwofilaj pou rezon komèsyal',
    cookies_consent_title: '4. Konsantman',
    cookies_consent_p1: 'Dapre règleman yo (RGPD, direktiv ePrivacy, rekòmandasyon CNIL), cookies ki estrikteman nesesè pou fonksyònman yon sèvis itilizatè a mande a pa bezwen konsantman davans.',
    cookies_consent_p2_html: 'Men, Dok\'péyi montre yon banyè enfòmasyon premye fwa ou vizite sit la pou fè ou konnen yo itilize cookies sa yo. Lè ou klike sou « J\'accepte », ou konfime ou pran nòt sa. Banyè a pap parèt ankò nan pwochen vizit ou yo.',
    cookies_manage_title: '5. Kijan pou jere cookies yo?',
    cookies_manage_intro: 'Ou ka nenpòt ki lè efase cookies ki deja depoze yo oswa anpeche yo depoze atravè paramèt navigatè ou a :',
    cookies_manage_chrome: '<strong>Chrome :</strong> Paramètres → Confidentialité et sécurité → Cookies et autres données des sites',
    cookies_manage_firefox: '<strong>Firefox :</strong> Paramètres → Vie privée et sécurité → Cookies et données de sites',
    cookies_manage_safari: '<strong>Safari :</strong> Préférences → Confidentialité → Gérer les données du site web',
    cookies_manage_edge: '<strong>Edge :</strong> Paramètres → Cookies et autorisations de site',
    cookies_manage_p2_html: 'Ou ka vide depo lokal la tou (<code>localStorage</code> / <code>sessionStorage</code>) depi nan zouti devlopman navigatè ou a.',
    cookies_manage_warning_html: '<strong>Atansyon :</strong> bloke cookies ki estrikteman nesesè yo ka anpeche sit la mache byen (pèt panyen ou, dekoneksyon…).',
    cookies_changes_title: '6. Chanjman',
    cookies_changes_p1: 'Politik cookies sa a ka mete ajou pou reflete evolisyon teknik oswa regilasyon yo. Nenpòt chanjman enpòtan ap endike sou paj sa a epi, si sa nesesè, atravè yon nouvo banyè konsantman.',
    cookies_contact_title: '7. Kontak',
    cookies_contact_intro: 'Pou nenpòt kestyon sou cookies yo :',
    cookies_footer_home: 'Akèy',
    leg_nav_home: 'Retounen sou akèy la',
    leg_title: 'Enfòmasyon legal',
    leg_subtitle: 'Paj konpatibilite ki rasanble enfòmasyon legal itil yo epi ki voye sou paj legal detaye Dok\'péyi yo.',
    leg_compat_html: '<strong>Paj legacy sa a konsève pou konpatibilite.</strong> Tèks legal referans yo disponib kounye a sou paj dedye pou Mentions légales, CGV, Konfidansyalite ak Cookies.',
    leg_toc_title: 'Somè',
    leg_toc_mentions: '1. Mentions légales',
