    leg_mentions_title: '1. Mentions légales',
    leg_mentions_intro: 'Enfòmasyon sou editè a, hosting ak piblikasyon an konsève sou yon paj dedye pou asire mizajou legal san doublon.',
    leg_open_notice: 'Louvri paj legal detaye a',
    leg_cgu_title: '2. Kondisyon Jeneral Itilizasyon',
    leg_cgu_intro: 'Itilizasyon sit Dok\'péyi a vle di ou aksepte kondisyon jeneral itilizasyon sa yo. Yo tabli règ aksè ak responsablite itilizatè a ak Dok\'péyi.',
    leg_cgu_warning_html: '<strong>Enpòtan:</strong> dokiman Dok\'péyi jenere yo se yon èd pou redaksyon. Yo dwe relire epi verifye avan nenpòt itilizasyon ofisyèl.',
    leg_cgu_li1: 'Sèvis la disponib 24 sou 24, 7 jou sou 7, eksepte antretyen, ensidan teknik oswa fòs majè.',
    leg_cgu_li2: 'Itilizatè a dwe bay enfòmasyon egzak epi pa dwe sèvi ak sèvis la pou rezon ilegal, fwod oswa nuizib.',
    leg_cgu_li3: 'Kontni sit la (logo, entèfas, tèks, estrikti) pwoteje epi pa ka repwodui san otorizasyon.',
    leg_cgu_li4: 'Dok\'péyi pa yon kabinè avoka ni yon administrasyon; itilizatè a rete sèl responsab pou depo ak itilizasyon final dokiman an.',
    leg_cgv_title: '3. Kondisyon Jeneral Vant',
    leg_cgv_intro: 'Pri yo, peman, livrezon, ranbousman ak avètisman sou entèlijans atifisyèl yo detaye nan CGV konplè yo.',
    leg_cgv_prices_intro: 'Rappel sou tarif piblik ki afiche kounye a :',
    leg_cgv_payment: 'Peman an sekirize. Done bankè yo trete pa prestataire dedye yo epi yo pa pase kòm sa atravè Dok\'péyi.',
    leg_cgv_delivery: 'Sèvis ki senp yo ka livre imedyatman; sèvis ki mande relikti imen fini nan 24 a 48 èdtan.',
    leg_cgv_refund: 'Règ ranbousman, retraktasyon ak medyasyon yo presize sou paj CGV referans lan.',
    leg_open_terms: 'Louvri CGV detaye yo',
    leg_conf_title: '4. Konfidansyalite ak RGPD',
    leg_conf_intro: 'Dok\'péyi trete done pèsonèl ki nesesè pou jenerasyon, peman ak livrezon dokiman yo, dapre RGPD ak lwa franse.',
    leg_conf_li1: 'Done idantifikasyon ak kontak',
    leg_conf_li2: 'Done ki lye ak demann administratif oswa pwofesyonèl la',
    leg_conf_li3: 'Done teknik ak peman ki estrikteman nesesè',
    leg_open_privacy: 'Louvri politik konfidansyalite detaye a',
    leg_cookies_title: '5. Politik cookies',
    leg_cookies_intro: 'Dok\'péyi adopte yon politik senp: sèlman cookies ak depo ki estrikteman nesesè pou sèvis la ak peman an.',
    leg_cookies_li1: 'Memorizasyon banyè cookies la ak lang ki chwazi a',
    leg_cookies_li2: 'Sovgad tanporè wizard la nan navigatè a',
    leg_cookies_li3: 'Cookies Stripe sèlman pandan peman an',
    leg_open_cookies: 'Louvri politik cookies detaye a',
