    ml_law_title: 'Toepasselijk recht',
    ml_law_p1_html: 'Deze vermeldingen vallen onder het Franse recht. Elk geschil valt uitsluitend onder de bevoegdheid van de Franse rechtbanken; de bevoegde rechtbank is die van <strong>Cayenne (Frans-Guyana)</strong>.',
    ml_contact_title: 'Contact',
