    conf_processors_intro: "تلجأ Dok'péyi إلى المتعهدين التاليين لتقديم الخدمة. وكل طرف منهم ملتزم باتفاقية معالجة بيانات (DPA) متوافقة مع المادة 28 من RGPD عند الاقتضاء:",
    conf_table_processor: 'المتعهد',
    conf_table_role: 'الدور',
    conf_table_location: 'الموقع',
