    leg_title: 'معلومات قانونية',
    leg_subtitle: 'صفحة توافق تجمع المعلومات القانونية المفيدة وتوجّه إلى الصفحات القانونية المفصلة الخاصة بـ Dok\'péyi.',
    leg_compat_html: '<strong>صفحة قديمة محفوظة للتوافق.</strong> النصوص القانونية المرجعية أصبحت الآن موزعة على الصفحات المخصصة للإشعارات القانونية وشروط البيع والخصوصية وملفات تعريف الارتباط.',
