    leg_mentions_title: '1. الإشعارات القانونية',
    leg_mentions_intro: 'يتم الحفاظ على معلومات الناشر والاستضافة والنشر في صفحة مخصصة لضمان تحديثها قانونياً من دون تكرار.',
    leg_open_notice: 'فتح الإشعارات القانونية المفصلة',
    leg_cgu_title: '2. شروط الاستخدام العامة',
    leg_cgu_intro: 'استخدام موقع Dok\'péyi يعني قبول شروط الاستخدام العامة هذه. وهي تنظّم الوصول إلى الخدمة والمسؤوليات الخاصة بالمستخدم وDok\'péyi.',
    leg_cgu_warning_html: '<strong>مهم:</strong> الوثائق التي تنشئها Dok\'péyi هي مساعدة في الصياغة فقط. يجب مراجعتها والتحقق منها قبل أي استخدام رسمي.',
    leg_cgu_li1: 'الخدمة متاحة على مدار الساعة طوال أيام الأسبوع، باستثناء الصيانة أو العطل التقني أو القوة القاهرة.',
    leg_cgu_li2: 'يجب على المستخدم تقديم معلومات دقيقة وعدم استخدام الخدمة لأغراض غير قانونية أو احتيالية أو ضارة.',
    leg_cgu_li3: 'محتوى الموقع (الشعار، الواجهة، النصوص، البنية) محمي ولا يجوز إعادة إنتاجه بدون إذن.',
    leg_cgu_li4: 'Dok\'péyi ليست مكتب محاماة ولا إدارة رسمية؛ ويظل المستخدم مسؤولاً عن الإيداع والاستخدام النهائي للوثيقة.',
    leg_cgv_title: '3. شروط البيع العامة',
    leg_cgv_intro: 'الأسعار والدفع والتسليم والاسترداد والتنبيهات المتعلقة بالذكاء الاصطناعي مفصلة في شروط البيع الكاملة.',
    leg_cgv_prices_intro: 'تذكير بالأسعار العامة المعروضة حالياً:',
    leg_cgv_payment: 'الدفع مؤمّن. تتم معالجة البيانات المصرفية من طرف المزودين المختصين ولا تمر بصفتها هذه عبر Dok\'péyi.',
    leg_cgv_delivery: 'يمكن تسليم الخدمات البسيطة فوراً؛ أما الخدمات التي تتطلب مراجعة بشرية فتنتهي خلال 24 إلى 48 ساعة.',
    leg_cgv_refund: 'قواعد الاسترداد والعدول والوساطة موضحة في صفحة شروط البيع المرجعية.',
