    conf_request_li3_html: 'Documents uploaded by the user for pre-filling (PDF or image analysed by <code>/api/extract-doc</code>)',
    conf_request_li4: 'Generated documents (CVs, letters, official correspondence, files, guides)',
    conf_payment_title: 'Payment data',
    conf_payment_p1_html: "Banking data (card number, security code...) <strong>never passes through Dok'péyi servers</strong>. It is processed directly by our payment provider (Stripe). Dok'péyi only keeps the transaction identifier and the amount paid for accounting and follow-up purposes.",
