    conf_retention_title: '4. Retention periods',
    conf_retention_li1_html: '<strong>Order data and generated documents:</strong> 12 months after the last order, then deletion or anonymised archiving.',
    conf_retention_li2_html: '<strong>Billing data:</strong> 10 years (French accounting obligation).',
    conf_retention_li3_html: '<strong>Technical data (rate-limit, logs):</strong> maximum 12 rolling months.',
    conf_retention_li4_html: '<strong>Cookie preferences:</strong> 30 days (local browser storage).',
    conf_processors_title: '5. Recipients and processors',
    conf_processors_intro: "Dok'péyi relies on the following processors to deliver the service. Each of them is bound by a data processing agreement (DPA) compliant with Article 28 GDPR where applicable:",
    conf_table_processor: 'Processor',
    conf_table_role: 'Role',
