    conf_proc_1_role: 'AI text generation',
    conf_proc_1_location: 'United States (standard contractual clauses)',
    conf_proc_2_role: 'Internal AI chat (fallback)',
    conf_proc_2_location: 'United States (standard contractual clauses)',
    conf_proc_3_role: 'Site and Edge Functions hosting',
    conf_proc_3_location: 'United States (standard contractual clauses)',
    conf_proc_4_role: 'Card payment processing',
    conf_proc_4_location: 'Ireland / United States',
    conf_proc_5_role: 'Realtime database (orders)',
    conf_proc_5_location: 'EU — europe-west1',
    conf_proc_6_role: 'Transactional email delivery',
    conf_proc_6_location: 'United States (standard contractual clauses)',
    conf_processors_p1_html: 'Data transfers outside the EU, in particular to the United States, are governed by the European Commission’s <strong>Standard Contractual Clauses</strong> and, where applicable, by the <strong>Data Privacy Framework</strong>.',
    conf_processors_p2: 'No personal data is sold, rented or transferred to third parties for commercial purposes.',
    conf_rights_title: '6. Your rights',
    conf_rights_intro_html: 'As a data subject, you have the following rights:',
    conf_rights_li1_html: '<strong>Right of access</strong> — obtain confirmation that your data is being processed and a copy of it.',
    conf_rights_li2_html: '<strong>Right to rectification</strong> — have inaccurate or incomplete data corrected.',
    conf_rights_li3_html: '<strong>Right to erasure</strong> — request deletion of your data (“right to be forgotten”) under certain conditions.',
    conf_rights_li4_html: '<strong>Right to restriction</strong> — request suspension of processing in certain cases.',
    conf_rights_li5_html: '<strong>Right to object</strong> — object to processing based on legitimate interest.',
    conf_rights_li6_html: '<strong>Right to portability</strong> — receive your data in a structured and readable format.',
    conf_rights_li7_html: '<strong>Right to withdraw consent</strong> at any time (for processing based on consent).',
    conf_rights_li8_html: '<strong>Right to define post-mortem instructions</strong> relating to your data.',
    conf_rights_request_html: 'To exercise these rights, send your request to <a href="mailto:contact@dok-peyi.fr">contact@dok-peyi.fr</a> and state your identity. A response will be provided within a maximum of <strong>one month</strong>.',
    conf_dpo_title: '7. Data Protection Officer (DPO)',
    conf_dpo_p1: "Dok'péyi is not legally required to appoint a DPO, but has designated a dedicated contact point for all questions relating to data protection:",
    conf_security_title: '8. Data security',
    conf_security_intro: "Dok'péyi implements appropriate technical and organisational measures to protect your data against destruction, loss, alteration or unauthorised disclosure:",
    conf_security_li1: 'Encryption of data in transit (HTTPS / TLS)',
    conf_security_li2: 'Firebase security rules (role-based access control)',
    conf_security_li3: 'Security HTTP headers (CSP, HSTS, X-Frame-Options...)',
    conf_security_li4: 'Administrator account authentication with brute-force protection',
    conf_security_li5: 'Rate-limiting on sensitive APIs',
    conf_security_li6: 'Signature verification (HMAC-SHA256) on payment webhooks',
    conf_authority_title: '9. Supervisory authority',
    conf_authority_p1: 'In accordance with Article 77 GDPR, you have the right to lodge a complaint with the French supervisory authority:',
