    conf_footer_home: 'Home',
    cookies_nav_home: 'Back home',
    cookies_title: 'Cookie policy',
    cookies_updated: 'Last updated: April 2026',
    cookies_summary_html: '<strong>🍪 In short — Dok\'péyi keeps cookies minimal:</strong><br>Only <strong>strictly necessary</strong> cookies are used to operate the service. No advertising cookies, no third-party trackers, no sharing with ad networks.',
    cookies_definition_title: '1. What is a cookie?',
    cookies_definition_p1: 'A cookie is a small text file placed on your device (computer, smartphone, tablet) by the browser when you visit a website. It allows the site to remember information about your visit (language, session, preferences).',
    cookies_definition_p2_html: 'Dok\'péyi also uses similar technologies: <code>localStorage</code> (browser local storage) and <code>sessionStorage</code> (session storage, cleared when the tab is closed).',
    cookies_used_title: '2. Cookies used on Dok\'péyi',
    cookies_used_intro: 'Only the following cookies, all strictly necessary for the service to work, are used:',
    cookies_table_name: 'Name',
    cookies_table_purpose: 'Purpose',
    cookies_table_duration: 'Duration',
    cookies_table_type: 'Type',
    cookies_cookie_ok_purpose: 'Remember your acceptance of the cookie banner',
    cookies_cookie_ok_duration: '30 days',
    cookies_cookie_draft_purpose: 'Temporary save of the order form (wizard)',
    cookies_cookie_draft_duration: 'Session (when the tab is closed)',
    cookies_cookie_lang_purpose: 'Remember the language chosen for the interface',
    cookies_cookie_lang_duration: '1 year',
    cookies_cookie_stripe_name: 'Stripe cookies',
    cookies_cookie_stripe_purpose: 'Secure the payment session (set only during payment via Stripe)',
    cookies_cookie_stripe_duration: 'Session',
    cookies_cookie_stripe_type: 'Strictly necessary third party',
    cookies_we_do_not_title: '3. What we do not do',
    cookies_we_do_not_li1: '❌ No advertising cookies, no behavioural targeting',
    cookies_we_do_not_li2: '❌ No third-party cookies for tracking purposes (Google Analytics, Facebook Pixel, etc.)',
    cookies_we_do_not_li3: '❌ No resale or sharing of data with ad networks',
    cookies_we_do_not_li4: '❌ No profiling for commercial purposes',
    cookies_consent_title: '4. Consent',
    cookies_consent_p1: 'Under applicable regulations (GDPR, ePrivacy directive, CNIL recommendations), cookies that are strictly necessary for the operation of a service requested by the user do not require prior consent.',
    cookies_consent_p2_html: 'Nevertheless, Dok\'péyi displays an information banner on your first visit to inform you about the use of these cookies. By clicking “J\'accepte”, you confirm that you have been informed. The banner will no longer appear on your subsequent visits.',
    cookies_manage_title: '5. How to manage cookies?',
    cookies_manage_intro: 'You can delete cookies that have already been placed at any time, or prevent them from being placed, via your browser settings:',
    cookies_manage_chrome: '<strong>Chrome :</strong> Settings → Privacy and security → Cookies and other site data',
    cookies_manage_firefox: '<strong>Firefox :</strong> Settings → Privacy and security → Cookies and site data',
    cookies_manage_safari: '<strong>Safari :</strong> Preferences → Privacy → Manage website data',
    cookies_manage_edge: '<strong>Edge :</strong> Settings → Cookies and site permissions',
    cookies_manage_p2_html: 'You can also clear local storage (<code>localStorage</code> / <code>sessionStorage</code>) from your browser development tools.',
    cookies_manage_warning_html: '<strong>Warning:</strong> blocking strictly necessary cookies may prevent the site from working properly (loss of your cart, logout…).',
    cookies_changes_title: '6. Changes',
    cookies_changes_p1: 'This cookie policy may be updated to reflect technical or regulatory developments. Any material change will be indicated on this page and, where appropriate, through a new consent banner.',
    cookies_contact_title: '7. Contact',
    cookies_contact_intro: 'For any question relating to cookies:',
    cookies_footer_home: 'Home',
    leg_nav_home: 'Back to home',
    leg_title: 'Legal information',
    leg_subtitle: "Compatibility page centralising key legal information and linking to Dok'péyi's detailed legal pages.",
    leg_compat_html: '<strong>Legacy page kept for compatibility.</strong> The detailed reference legal texts are now split across the dedicated Legal notice, Terms, Privacy and Cookies pages.',
    leg_toc_title: 'Contents',
    leg_toc_mentions: '1. Legal notice',
    leg_toc_cgu: '2. Terms of use',
    leg_toc_cgv: '3. Terms of sale',
    leg_toc_conf: '4. Privacy & GDPR',
    leg_toc_cookies: '5. Cookie policy',
    leg_mentions_title: '1. Legal notice',
    leg_mentions_intro: 'Publisher, hosting and publication information is maintained on a dedicated page to keep legal updates accurate and avoid duplication.',
    leg_open_notice: 'Open the detailed legal notice',
    leg_cgu_title: '2. Terms of use',
    leg_cgu_intro: "Using the Dok'péyi website implies acceptance of these terms of use. They govern access to the service and the respective responsibilities of the user and Dok'péyi.",
    leg_cgu_warning_html: '<strong>Important:</strong> documents generated by Dok\'péyi are drafting assistance only. They must be reviewed and checked before any official use.',
    leg_cgu_li1: 'The service is available 24/7 except in the event of maintenance, technical incident or force majeure.',
    leg_cgu_li2: 'Users must provide accurate information and must not use the service for unlawful, fraudulent or harmful purposes.',
    leg_cgu_li3: 'Site content (logo, interface, texts, structure) is protected and may not be reproduced without permission.',
    leg_cgu_li4: "Dok'péyi is neither a law firm nor a public administration; the user remains responsible for filing and final use of the document.",
    leg_cgv_title: '3. Terms of sale',
    leg_cgv_intro: 'Pricing, payment, delivery, refund rules and AI warnings are detailed in the full terms of sale.',
    leg_cgv_prices_intro: 'Reminder of the currently displayed public prices:',
    leg_cgv_payment: 'Payment is secure. Banking data is handled by dedicated providers and does not transit as such through Dok\'péyi.',
    leg_cgv_delivery: 'Simple services may be delivered immediately; services subject to human review are finalised within 24 to 48 hours.',
    leg_cgv_refund: 'Refund, withdrawal and mediation rules are set out on the reference Terms page.',
    leg_open_terms: 'Open the detailed terms',
    leg_conf_title: '4. Privacy & GDPR',
    leg_conf_intro: 'Dok\'péyi processes the personal data needed to generate, pay for and deliver documents in compliance with GDPR and French law.',
    leg_conf_li1: 'Identification and contact data',
    leg_conf_li2: 'Data related to the administrative or professional request',
