    leg_open_privacy: 'Open the detailed privacy policy',
    leg_cookies_title: '5. Cookie policy',
    leg_cookies_intro: 'Dok\'péyi follows a restrained approach: only cookies and storage strictly necessary for the service and payment to work.',
    leg_cookies_li1: 'Remembering the cookie banner and chosen language',
