    cgv_rate_dossier: 'Dosyé administrativ (CAF, lòjman, èd sosyal…)',
    cgv_rate_sejour: 'Tit séjou (gid pèsonnalizé)',
    cgv_rate_impot: 'Avi taks (konprann, èd, kouryé)',
    cgv_rate_naturalisation: 'Natiralizasyon (éligibilité, dosyé, lèt)',
    cgv_cv_options_title: 'Opsyon é sipléman CV',
    cgv_cv_options_intro: 'Modèl CV premium-yan ka vini an sipléman asou pri baz CV-a :',
    cgv_table_template: 'Modèl CV',
    cgv_table_supplement: 'Sipléman',
    cgv_cv_option_classic: 'Klasik (anndan pa défaut)',
    cgv_cv_option_corporate: 'Corporate',
    cgv_cv_option_impact: 'Impact',
    cgv_cv_option_elite: 'Elite',
    cgv_cv_option_prestige: 'Prestige',
    cgv_cv_option_executive: 'Executive',
    cgv_other_options_title: 'Lòt opsyon',
    cgv_other_option_translation_html: '<strong>Tradiksyon dokiman-an</strong> (anglé, kréyòl, pòtigè) : <span class="price">+3 €</span>',
    cgv_other_option_mods_html: '<strong>Modifikasyon siplémentè</strong> — <strong>2 modifikasyon ofè</strong> asou chak dokiman apré prévizyalizasyon. Aprésa, pri aplikab-la ké bay avan tout fakti é i ké mandé dakò klè kliyan-an.',
    cgv_section_3_title: '3. Kòmand é péman',
    cgv_section_3_p1: 'Kòmand-la ka fèt pa lentèfas sit-la (service.html) an twa étap : chwazi sèvis-la, rantré lenfòmasyon-yan, fè péman-an.',
    cgv_section_3_p2_html: 'Péman-an ka fèt an liy, an sékirité, pa <strong>Stripe</strong>. Péman manyèl pa <strong>PayPal</strong> é <strong>Mobile Money (Momo)</strong> disponib osi asou demann.',
    cgv_section_3_p3: 'Donné bankè-ya pa ka pasé asou sèvè Dok\'péyi : sé dirèkman founisè péman-an ki ka trété yo.',
    cgv_section_4_title: '4. Délè livrézon',
    cgv_section_4_p1_html: 'Jénérasyon dokiman-an pa lentèlijans atifisyèl sé <strong>près imédiat</strong> (kèk segonn). Dokiman-an ka prévizyalizé dépi jénérasyon-an fini.',
    cgv_section_4_p2_html: 'Pou sèvis ki bizwen an vérifikasyon manyèl pa an manm lékip-la (<strong>Tit séjou</strong>, <strong>Natiralizasyon</strong>), livrézon final-la ka fèt an <strong>24 a 48 èdtan</strong> apré validasyon administrativ-la, pa imèl.',
    cgv_section_4_p3_html: 'Pou rès sèvis-ya, livrézon-an ka fèt <strong>toutswit</strong> apré konfimasyon péman-an, pa imèl oben téléchajman dirèk.',
    cgv_section_5_title: '5. Politik ranbousman',
    cgv_refund_intro: 'Dapré atik L.221-28 Kòd konsomasyon-an, kliyan-an ni garanti tala :',
    cgv_refund_delay_html: '<strong>Dokiman pa livré an 72h</strong> apré péman (sòf si kliyan-an té mandé an délè oben pa réponn lékip-la) : ranbousman total asou demann.',
    cgv_refund_error_html: '<strong>Dokiman ki klèman fo oben pa ka sèvi</strong> : koreksyon gratis an priyorité oben, si sa pa posib, ranbousman an pati oben total dapré ka-a.',
    cgv_refund_tech_html: '<strong>Fot teknik oben fakti doub</strong> : ranbousman total an 14 jou.',
    cgv_refund_request_html: 'Tout demann ranbousman dwèt voyé an <a href="mailto:contact@dok-peyi.fr">contact@dok-peyi.fr</a> èk niméro kòmand-an é rézon-an.',
    cgv_retract_title: '6. Dwa rétraktasyon',
    cgv_retract_p1_html: 'Dapré atik L.221-18 Kòd konsomasyon-an, kliyan-an ni an délè <strong>14 jou kalandriyé</strong> apati konfimasyon kòmand-an pou sèvi dwa rétraktasyon li, san i ni pou jistifié pyès rézon.',
    cgv_retract_p2_html: '<strong>Éksèpsyon — atik L.221-28 13° Kòd konsomasyon-an :</strong> dwa rétraktasyon-an pa ka sèvi pou kontra ki ka bay <strong>kontni dijital ki pa asou sipò materyèl</strong> lè ekzékisyon-an koumansé apré konsantman klè konsomatè-a é renonsyasyon klè asou dwa rétraktasyon-an. Lè kliyan-an ka validé kòmand li, i ka rekonèt dokiman-an ké livré touswit é i ka renonsé asou dwa rétraktasyon li pou kontni tala.',
    cgv_retract_p3: 'Dwa rétraktasyon-an ka rété valab si dokiman-an pa livré an délè ki té prévwè-a (atik 4).',
    cgv_ai_title: '7. Avètisman asou lentèlijans atifisyèl',
    cgv_disclaimer_html: '<strong>⚠️ Avètisman IA — li sa byen</strong><br><br>Dokiman jénéré pa lentèlijans atifisyèl ka bay kon èd pou rédaksyon. Yo pa sé an konsèy jiridik pwofésyonèl.<br><br>Pou démach konplèks (<strong>tit séjou, natiralizasyon, litij fiskal, rekou administrativ</strong>), nou ka rèkomandé fò konsilté an pwofésyonèl lajistis (avoka) oben an asosyasyon espesyalizé — an patikilyé <strong>CIMADE Guyane</strong> (èd gratis pou étranjé) oben an pwen aksè dwa.<br><br>Dok\'péyi pa ka pran pyès responsablité si an dokiman jénéré sèvi san vérifikasyon pou an démach ofisyèl.',
    cgv_liability_title: '8. Responsablité',
    cgv_liability_p1: 'Dok\'péyi ka fè tout sa i pé pou asiré bon kalite dokiman-yan. Men kliyan-an ka rété responsab pou vérifikasyon é itilizasyon dokiman yo remèt li-a.',
    cgv_liability_p2: 'Dok\'péyi pa sa pran responsablité pou :',
    cgv_liability_li1: 'konsekans enfòmasyon ki pa jis kliyan-an bay ;',
    cgv_liability_li2: 'refi an démach administrativ pa administrasyon konpétan-an ;',
    cgv_liability_li3: 'an entèripsyon tanporèr sèvis-la lié ké ébèjman-an oben sèvis tiers ;',
    cgv_liability_li4: 'an mové itilizasyon dokiman-an pa kliyan-an oben an lòt moun.',
    cgv_data_title: '9. Pwotèksyon donné pèsonèl',
    cgv_data_p1_html: 'Dok\'péyi ka ranmasé é trété donné pèsonèl kliyan-ya dapré RGPD-a. Pou détay asou trètman-yan, objektif-ya, tan konsèrvasyon-an é dwa kliyan-an, gadé <a href="/confidentialite">politik konfidansyalité</a> nou-an.',
    cgv_changes_title: '10. Chanjman CGV-a',
    cgv_changes_p1: 'Dok\'péyi ka rézèrvé dwa pou modifié CGV tala nenpòt lè. CGV aplikab-la sé sa ki té an vigè lè kòmand-an pasé. Tout gwo chanjman ké notifié pa imèl ba kliyan ki konsèné yo.',
    cgv_jurisdiction_title: '11. Lwa aplikab é jiridiksyon konpétan',
    cgv_jurisdiction_p1_html: 'CGV tala soumèt anba <strong>lwa fransé</strong>.',
    cgv_jurisdiction_p2_html: 'Si pa ni solisyon amikal, tout litij asou entèprétasyon oben égzékisyon yo ka rivé sèlman anba konpétans <strong>Tribinal jidisyè Cayenne</strong>.',
    cgv_jurisdiction_p3: 'Dapré atik L.612-1 Kòd konsomasyon-an, kliyan konsomatè-a pé sèvi gratis ké an médiatè konsomasyon pou chaché an rézolusyon amikal pou litij-la. Kowòdoné médiatè-a ké bay asou demann.',
    cgv_contact_title: '12. Kontak',
    cgv_contact_intro: 'Pou tout kestyon asou CGV tala oben asou an kòmand :',
