    conf_request_li4: 'Dokiman yé jenéré (CV, lèt, kouryé, dosyé, gid)',
    conf_payment_title: 'Donné péman',
    conf_payment_p1_html: "Donné bankè-ya (niméro kat-la, kriptogram...) <strong>pa janmen ka pasé asou sèrvèr Dok'péyi</strong>. Yé ka trété drèt pa préstata péman nou-an (Stripe). Dok'péyi ka gardé sèlman idantifyan tranzaksyon-an é montan péyé-a pou rézon kontabilité é swivi.",
    conf_technical_title: 'Donné teknik',
    conf_technical_li1: 'Adrès IP (yé ka sèvi pou rate-limiting, pa ka rété stoké lontan)',
