    conf_purpose_5: 'Obligasyon kontabilité é fiskalité',
    conf_basis_5: 'Obligasyon légal (art. 6.1.c RGPD)',
    conf_retention_title: '4. Tan konsèrvasyon',
    conf_retention_li1_html: '<strong>Donné komand é dokiman yé jenéré:</strong> 12 mwa apré dènyé komand-an, apré sa yé ka efasé oben achivé an fason anonim.',
    conf_retention_li2_html: '<strong>Donné faktirasyon:</strong> 10 lanné (obligasyon kontab fransé).',
    conf_retention_li3_html: '<strong>Donné teknik (rate-limit, logs):</strong> 12 mwa glisan maksimòm.',
    conf_retention_li4_html: '<strong>Préférans cookies:</strong> 30 jou (stokaj lokal an navigatè-a).',
    conf_processors_title: '5. Réseptè é soutretan',
    conf_processors_intro: "Dok'péyi ka sèvi ké soutretan sila-ya pou bay sèvis-a. Chak yonn ni an kontra trètman donné (DPA) ki konfòm ké lartik 28 RGPD-a lè sa ka apliké:",
    conf_table_processor: 'Soutretan',
